// documentation for more info.
func (u *CreativeLinkUpsertBulk) Update(set func(*CreativeLinkUpsert)) *CreativeLinkUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&CreativeLinkUpsert{UpdateSet: update})
	}))
	return u
}

